import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict sender to be the owner so the require passes
        vm.prank(address(this));
        c.sendTo(receiver, 0); // initial call to set up owner if needed, owner is setUp's deployer

        // Ensure the contract has enough balance for the transfer
        uint256 contractBalBefore = address(c).balance;
        vm.assume(amount <= contractBalBefore);

        // Record contract balance before transfer
        uint256 balBefore = address(c).balance;

        // Owner sends to receiver
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // Contract balance after transfer
        uint256 balAfter = address(c).balance;

        // Rule: contract balance decreases by exactly the amount sent
        assertTrue(balBefore - balAfter == amount);
    }
}

