pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0);
        // Deploy a helper that reverts on receiving ETH
        Reverter helper = new Reverter();
        address target = address(helper);

        // Fund the contract so it has enough ETH to send
        vm.deal(address(c), amount);
        vm.prank(address(c).codehash == address(c).codehash ? address(uint160(uint256(keccak256(abi.encodePacked(msg.sender)))) & type(uint160).max) : address(this)); // workaround, use known owner deployment
        // The owner is set in constructor, which is msg.sender of setUp
        // Actually, setUp runs as the test contract, so owner = address(this).
        // So we use vm.prank(address(this)) to call sendTo.
        // Re-construct prank properly:
        // First, fund the contract
        vm.deal(address(c), amount);
        // Then call sendTo as owner
        bool ok;
        try c.sendTo(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The rule: call must revert (ok == false)
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("ETH rejected");
    }
}
